        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Advanced Excel Functions & Data Sorting/Filtering", 1, "Which Excel logical function returns one value if a condition is true and another if false?", "MCQ", "=IF()", "=AND()", "=OR()", "=NOT()", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Advanced Excel Functions & Data Sorting/Filtering", 1, "Which function in Excel looks up a value in the leftmost column of a table and returns a corresponding value from another column?", "MCQ", "=VLOOKUP()", "=HLOOKUP()", "=INDEX()", "=MATCH()", "A", null);
