        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Advanced Excel Functions & Data Sorting/Filtering", 1, "Displaying only the rows in a dataset that meet specific criteria while temporarily hiding the rest is called _______.", "MCQ", "Filtering (AutoFilter)", "Sorting", "Deleting", "Wrapping", "A", null);
