        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Advanced Excel Functions & Data Sorting/Filtering", 2, "The function that counts cells matching a specific condition is =_______().", "FILL_BLANK", "COUNTIF", "COUNTIF", "", "", "COUNTIF", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Advanced Excel Functions & Data Sorting/Filtering", 2, "In `=VLOOKUP(lookup_value, table_array, col_index, FALSE)`, FALSE indicates an _______ match.", "FILL_BLANK", "Exact", "Exact", "", "", "Exact", null);
