        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Computer Network Basics & Topologies", 1, "Which network covers an entire country or spans across the globe (e.g. the Internet)?", "MCQ", "Wide Area Network (WAN)", "LAN", "PAN", "SAN", "A", null);
