        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Advanced Data Management & Networks", "CBSE 7 - Computer Network Basics & Topologies", 1, "The physical or logical layout arrangement of connected nodes and cables in a network is called Network _______.", "MCQ", "Topology", "Protocol", "Bandwidth", "IP Address", "A", null);
