        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 1, "Which transport protocol is connectionless, faster than TCP, and used in video streaming and online gaming?", "MCQ", "UDP (User Datagram Protocol)", "TCP", "BGP", "SSH", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 1, "What is the fundamental role of DNS (Domain Name System)?", "MCQ", "Translating human-readable domain names (e.g., example.com) into numeric IP addresses (e.g., 93.184.216.34)", "Formatting web pages with CSS", "Managing computer battery power", "Blocking email attachments", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 1, "Which protocol encrypts web traffic using SSL/TLS cryptographic certificates?", "MCQ", "HTTPS (Hypertext Transfer Protocol Secure)", "HTTP", "Telnet", "FTP", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 1, "An IPv4 address consists of _______ bits separated into 4 octets, while IPv6 consists of _______ bits.", "MCQ", "32 bits, 128 bits", "16 bits, 64 bits", "64 bits, 256 bits", "8 bits, 32 bits", "A", null);
