        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 2, "IPv4 addresses use _______ bits in total.", "FILL_BLANK", "32", "32, 32-bit", "", "", "32", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 2, "The network hardware that forwards data packets between different IP subnets is a _______.", "FILL_BLANK", "Router", "Router, Gateway", "", "", "Router", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 2, "The unique 48-bit hardware identifier burned into a Network Interface Card is the _______ address.", "FILL_BLANK", "MAC", "MAC, MAC address", "", "", "MAC", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 3, "How does a Packet Switching network transmit large multimedia files over the Internet?", "MCQ", "Splitting data into discrete indexed packets that travel independently across optimal routes and reassemble at the destination", "Sending one continuous uninterrupted electrical stream", "Printing out papers and scanning them", "Compressing everything into a single 1-byte file", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 3, "What is the key difference between a MAC address and an IP address?", "MCQ", "MAC address is permanent physical hardware identifier (Data Link Layer); IP address is dynamic logical address (Network Layer)", "MAC address changes on every reboot", "IP address is burned into the motherboard", "Both are identical 16-bit numbers", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 3, "Which network security system monitors and filters incoming and outgoing network traffic based on predetermined security rules?", "MCQ", "Firewall", "Web Browser", "Screen Saver", "Defragmenter", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 3, "What type of cyberattack floods a target web server with excessive traffic requests from compromised botnets to make it unavailable?", "MCQ", "DDoS (Distributed Denial of Service) Attack", "Phishing Scam", "SQL Injection", "Keylogger", "A", null);
        addQuestionIfMissing(school, board, classLevel, "Unit 1 – Networking, Web Technologies & Cyber Safety", "CBSE 10 - Internet Architecture, Protocols & Web Standards", 4, "A company wants to secure its remote employees' communication over public Wi-Fi networks. Which technology creates an encrypted private tunnel over the public internet?", "MCQ", "VPN (Virtual Private Network)", "Dial-up Modem", "Telnet Terminal", "Public FTP Server", "A", null);
