        addQuestionIfMissing(school, board, classLevel, "Unit 2 – Advanced HTML5 & CSS Web Development", "CBSE 10 - Semantic Web, Tables, Forms & CSS Box Model", 2, "HTML form element used to create multi-line text input is <_______>.", "FILL_BLANK", "textarea", "textarea", "", "", "textarea", null);
