        addQuestionIfMissing(school, board, classLevel, "Unit 3 – Database Management Systems & SQL", "CBSE 10 - Relational Database Concepts & Structured Query Language", 4, "A school database has table `Students (RollNo INT PRIMARY KEY, Name VARCHAR(50), Marks INT, City VARCHAR(30))`. Which query finds students from 'Chennai' with marks > 90?", "MCQ", "SELECT * FROM Students WHERE City = 'Chennai' AND Marks > 90;", "SELECT ALL Students IN 'Chennai' IF Marks > 90;", "FIND Students WHERE City IS 'Chennai' AND Marks > 90;", "FILTER Students ON City='Chennai' AND Marks > 90;", "A", null);
